import { supabase } from "@/integrations/supabase/client";
import type { MoneyPlan } from "@/lib/moneyGuard";

/**
 * Typed wrappers for the money guard (D4 step 1b). The RPCs are newer than
 * src/integrations/supabase/types.ts (regenerated by the conductor after the
 * paste), hence the one cast here and nowhere else. Every call is the signed-in
 * admin's own: the database decides the tier and refuses anyone else.
 */
const rpc = (name: string, args: Record<string, unknown>) => (supabase as any).rpc(name, args);

export interface MoneyError { code: string; kind?: string | null; message: string }

const asError = (e: any): MoneyError => {
  const sql = String(e?.code ?? "");
  const map: Record<string, string> = {
    HC010: "reason_too_short", HC011: "token_stale", HC012: "confirm_required", HC013: "correction_reason_required",
    HC025: "attendance_requires_checked_path", HC050: "guard_broken", HC060: "approval_required", PGRST202: "guard_not_installed",
    "42883": "guard_not_installed", "42501": "forbidden",
  };
  const code = sql === "HC015" ? String(e?.message ?? "refused") : map[sql] ?? "unexpected";
  const kind = /kind=([a-z_]+)/.exec(String(e?.details ?? e?.detail ?? ""))?.[1] ?? null;
  return { code, kind, message: String(e?.message ?? "") };
};

export async function previewMoneyChange(entity: string, op: string, args: Record<string, unknown>):
  Promise<{ plan: MoneyPlan } | { error: MoneyError }> {
  const { data, error } = await rpc("money_change_preview", { p_entity: entity, p_op: op, p_args: args });
  if (error) return { error: asError(error) };
  return { plan: data as MoneyPlan };
}

export async function confirmMoneyChange(entity: string, op: string, args: Record<string, unknown>,
  ack: { reason: string | null; token: string | null; confirm: boolean; correction_reason: string | null }):
  Promise<{ result: any } | { error: MoneyError }> {
  const { data, error } = await rpc("money_change_checked", {
    p_entity: entity, p_op: op, p_args: args, p_reason: ack.reason, p_token: ack.token,
    p_confirm: ack.confirm, p_correction_reason: ack.correction_reason, p_context: { source: "screen" },
  });
  if (error) return { error: asError(error) };
  return { result: data };
}

/** Recalculate the bills a checked change reached (guarded-change-refresh, at most 25 a call). */
export async function refreshMoneyChange(overrideId: string): Promise<{ tuition: any } | { error: MoneyError }> {
  const { data, error } = await supabase.functions.invoke("guarded-change-refresh", {
    body: { action: "refresh", override_id: overrideId },
  });
  if (error) return { error: { code: "refresh_failed", message: String(error.message ?? error) } };
  return { tuition: data?.tuition ?? null };
}
